import { Asset } from 'expo-asset';
import { File } from 'expo-file-system';

import type { Repositories } from '@/services/database/repositories';
import { audioFileFor } from '@/services/filesystem/musicStorage';
import { createId } from '@/utils/id';

/**
 * Development-only seed data: synthetic tones generated by
 * scripts/generate-sample-audio.sh, so the library, player and playlists can
 * be exercised before the backend exists. Imported with provider "sample".
 */
const SAMPLES = [
  {
    key: 'sample-1',
    title: 'Crimson Sunrise',
    creator: 'AudioVault Demo',
    module: require('../../../assets/samples/sample-1.mp3'),
  },
  {
    key: 'sample-2',
    title: 'Night Drive',
    creator: 'AudioVault Demo',
    module: require('../../../assets/samples/sample-2.mp3'),
  },
  {
    key: 'sample-3',
    title: 'Static Bloom',
    creator: 'Synth Lab',
    module: require('../../../assets/samples/sample-3.mp3'),
  },
  {
    key: 'sample-4',
    title: 'Low Orbit',
    creator: 'Synth Lab',
    module: require('../../../assets/samples/sample-4.mp3'),
  },
] as const;

const SAMPLE_DURATION_SECONDS = 30;

/** Copies the bundled samples into private storage. Returns how many were added. */
export async function loadSampleLibrary(repos: Repositories): Promise<number> {
  let added = 0;
  for (const sample of SAMPLES) {
    if (await repos.songs.findBySource('sample', sample.key)) continue;
    const asset = Asset.fromModule(sample.module);
    await asset.downloadAsync();
    if (!asset.localUri) throw new Error(`Could not load ${sample.key}.`);

    const id = createId();
    const destination = audioFileFor(id);
    await new File(asset.localUri).copy(destination);

    await repos.songs.insert({
      id,
      provider: 'sample',
      sourceId: sample.key,
      sourceUrl: `sample://${sample.key}`,
      title: sample.title,
      creator: sample.creator,
      duration: SAMPLE_DURATION_SECONDS,
      thumbnailUrl: null,
      localAudioUri: destination.uri,
      localArtworkUri: null,
      fileSize: destination.size,
    });
    added += 1;
  }
  return added;
}
